@RestController
@RequestMapping("/api/v1/auth")
public class AuthController {

    private static final String LOGIN_SUCCESS_URL = "/dashboard";
    private static final String LOGIN_FAILURE_URL = "/login?error=1";

    private final UserService userService;
    private final RedirectValidator redirectValidator;

    public AuthController(UserService userService, RedirectValidator redirectValidator) {
        this.userService = userService;
        this.redirectValidator = redirectValidator;
    }

    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest request, HttpServletRequest httpRequest) {
        // 1. 参数校验
        if (request.getUsername() == null || request.getUsername().trim().isEmpty()
                || request.getPassword() == null) {
            return ResponseEntity.badRequest().body("Invalid credentials");
        }

        // 2. 业务逻辑：用户认证
        User user = userService.authenticate(request.getUsername(), request.getPassword());
        if (user == null) {
            // 3. 失败时重定向（无用户可控输入）
            return ResponseEntity.ok().body(new LoginResponse(false, LOGIN_FAILURE_URL));
        }

        // 4. 成功时，从请求头获取重定向地址（用户可控）
        String requestedRedirect = httpRequest.getHeader("X-Redirect-Url");
        String safeRedirect;

        if (requestedRedirect != null && !requestedRedirect.isEmpty()) {
            // 5. 防御：URL 规范化 + 白名单校验
            safeRedirect = redirectValidator.validateAndNormalize(requestedRedirect);
            if (safeRedirect == null) {
                // 6. 校验失败，回退到默认地址
                safeRedirect = LOGIN_SUCCESS_URL;
            }
        } else {
            safeRedirect = LOGIN_SUCCESS_URL;
        }

        // 7. 生成 token 并返回
        String token = userService.generateToken(user.getId());
        return ResponseEntity.ok()
                .header("Location", safeRedirect)
                .body(new LoginResponse(true, safeRedirect, token));
    }
}

