#define MAX_PKT_SIZE 256
#define HEADER_SIZE 4

typedef struct {
    uint8_t data[MAX_PKT_SIZE];
    uint16_t len;
} packet_t;

static int process_payload(const uint8_t *payload, uint16_t payload_len) {
    // line 13: payload_len is bounded by caller, but double-check for defense-in-depth
    if (payload_len > MAX_PKT_SIZE - HEADER_SIZE) {
        return -1;
    }

    uint8_t *buffer = (uint8_t *)malloc(payload_len);
    if (!buffer) {
        return -2;
    }

    memcpy(buffer, payload, payload_len);

    // Simulate processing
    uint32_t checksum = 0;
    for (uint16_t i = 0; i < payload_len; i++) {
        checksum += buffer[i];
    }

    free(buffer);
    buffer = NULL;  // line 31: prevent dangling pointer

    return (int)(checksum % 100);
}

int handle_packet(packet_t *pkt) {
    if (!pkt || pkt->len > MAX_PKT_SIZE) {
        return -3;
    }

    // line 39: validate header length before parsing
    if (pkt->len < HEADER_SIZE) {
        return -4;
    }

    uint16_t payload_len = pkt->len - HEADER_SIZE;

    // line 44: payload_len is always < MAX_PKT_SIZE due to pkt->len check
    return process_payload(pkt->data + HEADER_SIZE, payload_len);
}

int main(void) {
    packet_t pkt;
    memset(&pkt, 0, sizeof(pkt));

    // Simulate receiving a packet
    pkt.len = 10;  // header(4) + payload(6)
    memcpy(pkt.data, "\x01\x02\x03\x04", HEADER_SIZE);
    memcpy(pkt.data + HEADER_SIZE, "abcdef", 6);

    int result = handle_packet(&pkt);
    printf("Result: %d\n", result);
    return 0;
}

#include <cstdint>
#include <vector>
#include <stdexcept>

#define MAX_PIXEL_VALUE 255
#define MAX_DIMENSION 8192

class ImageDecoder {
private:
    std::vector<uint8_t> buffer;
    size_t width;
    size_t height;

    bool validateDimensions(uint32_t w, uint32_t h) {
        // 防御1: 维度上限检查，防止整数溢出后的超大值通过
        if (w > MAX_DIMENSION || h > MAX_DIMENSION) {
            return false;
        }
        // 防御2: 乘积溢出检查，使用除法避免乘法溢出
        if (w != 0 && h > SIZE_MAX / w) {
            return false;
        }
        return true;
    }

    void processPixelRow(uint8_t* rowData, size_t rowSize) {
        // 防御3: 行内像素处理，确保访问在buffer范围内
        for (size_t i = 0; i < rowSize; ++i) {
            if (rowData[i] > MAX_PIXEL_VALUE) {
                rowData[i] = MAX_PIXEL_VALUE;
            }
        }
    }

public:
    ImageDecoder() : width(0), height(0) {}

    bool decodeHeader(uint32_t w, uint32_t h) {
        if (!validateDimensions(w, h)) {
            return false;
        }

        width = w;
        height = h;

        // 防御4: 使用size_t进行乘法，并在分配前再次验证
        size_t totalSize = static_cast<size_t>(w) * static_cast<size_t>(h) * 3; // RGB
        if (totalSize > buffer.max_size()) {
            return false;
        }

        try {
            buffer.resize(totalSize);
        } catch (const std::bad_alloc&) {
            return false;
        }

        return true;
    }

    bool decodeImage(const uint8_t* compressedData, size_t dataSize) {
        if (compressedData == nullptr || dataSize < sizeof(uint32_t) * 2) {
            return false;
        }

        // 从压缩数据中读取宽高
        uint32_t w = 0, h = 0;
        std::memcpy(&w, compressedData, sizeof(uint32_t));
        std::memcpy(&h, compressedData + sizeof(uint32_t), sizeof(uint32_t));

        if (!decodeHeader(w, h)) {
            return false;
        }

        // 防御5: 确保压缩数据足够处理所有像素行
        size_t requiredDataSize = width * height * 3;
        if (dataSize < requiredDataSize + sizeof(uint32_t) * 2) {
            buffer.clear();
            return false;
        }

        // 逐行处理，传递buffer内部指针
        for (size_t row = 0; row < height; ++row) {
            uint8_t* rowPtr = buffer.data() + row * width * 3;
            processPixelRow(rowPtr, width * 3);
        }

        return true;
    }
};

